param([Parameter(Mandatory)][string]$RuntimeRoot,[Parameter(Mandatory)][string]$StorageRoot,[Parameter(Mandatory)][string]$ExpectedExe,[Parameter(Mandatory)][string]$OutputRoot)
$ErrorActionPreference='Stop';$deadline=[datetime]::UtcNow.AddSeconds(1050);$writer=$null
try{
 $receipt=$null;while(!$receipt -and [datetime]::UtcNow -lt $deadline -and !(Test-Path "$StorageRoot/system-stop")){foreach($d in @(Get-ChildItem "$RuntimeRoot/Attempts" -Directory -ErrorAction SilentlyContinue)){if(!(Test-Path "$($d.FullName)/runtime.Observe.desktop-process.json")){continue};$o=Get-Content "$($d.FullName)/owner.json" -Raw|ConvertFrom-Json;if([IO.Path]::GetFullPath($o.storage) -eq [IO.Path]::GetFullPath($StorageRoot)){$receipt=Get-Content "$($d.FullName)/runtime.Observe.desktop-process.json" -Raw|ConvertFrom-Json;break}};if(!$receipt){Start-Sleep -Milliseconds 100}}
 if(!$receipt -or $receipt.inputDesktopActive -or $receipt.exe -ne $ExpectedExe){throw 'Owned inactive Player required'};$playerPid=$receipt.pid;$proc=Get-Process -Id $playerPid;if($proc.Path -ne $ExpectedExe){throw 'PID identity conflict'}
 $writer=[IO.StreamWriter]::new("$OutputRoot/system.csv");$writer.WriteLine('utc,pid,cpu_total_ms,working_set_bytes,private_bytes');$n=0
 while(!(Test-Path "$StorageRoot/system-stop") -and [datetime]::UtcNow -lt $deadline){$proc.Refresh();if($proc.HasExited){break};$now=[datetime]::UtcNow;$writer.WriteLine(($now.ToString('o')+','+$playerPid+','+$proc.TotalProcessorTime.TotalMilliseconds+','+$proc.WorkingSet64+','+$proc.PrivateMemorySize64));$writer.Flush()
  try{$pdh=Get-Counter -Counter '\GPU Process Memory(*)\Dedicated Usage','\GPU Process Memory(*)\Shared Usage','\GPU Process Memory(*)\Total Committed' -MaxSamples 1 -ErrorAction Stop;$samples=@($pdh.CounterSamples|Where-Object {$_.InstanceName -match ('^pid_'+$playerPid+'_')}|Select-Object Path,InstanceName,CookedValue,RawValue,Status,Timestamp);@{utc=[datetime]::UtcNow.ToString('o');pid=$playerPid;api='PDH';matching=$samples;allInstanceNames=@($pdh.CounterSamples.InstanceName|Sort-Object -Unique);status=$(if($samples.Count){'OBSERVED'}else{'NOT_RUN'})}|ConvertTo-Json -Depth 6 -Compress|Add-Content "$OutputRoot/gpu-pdh.jsonl"}catch{@{utc=[datetime]::UtcNow.ToString('o');pid=$playerPid;api='PDH';status='NOT_RUN';error=$_.Exception.ToString()}|ConvertTo-Json -Compress|Add-Content "$OutputRoot/gpu-pdh.jsonl"}
  if($n -lt 3){try{$all=Get-CimInstance Win32_PerfFormattedData_GPUPerformanceCounters_GPUProcessMemory -ErrorAction Stop;@{utc=[datetime]::UtcNow.ToString('o');api='WMI-unfiltered-then-PID';pid=$playerPid;matching=@($all|Where-Object Name -match ('^pid_'+$playerPid+'_')|Select-Object Name,DedicatedUsage,SharedUsage,TotalCommitted);allNames=@($all.Name)}|ConvertTo-Json -Depth 5 -Compress|Add-Content "$OutputRoot/gpu-wmi.jsonl"}catch{@{utc=[datetime]::UtcNow.ToString('o');api='WMI';status='NOT_RUN';error=$_.Exception.ToString()}|ConvertTo-Json -Compress|Add-Content "$OutputRoot/gpu-wmi.jsonl"}};$n++;Start-Sleep -Milliseconds 1000
 };@{status='PASS';pid=$playerPid;iterations=$n;scope='Exact process system CPU/memory and separately logged GPU capability, GPU errors do not become zeros'}|ConvertTo-Json|Set-Content "$OutputRoot/receipt.json"
}catch{$_|Out-String|Set-Content "$OutputRoot/error.txt";exit 1}finally{if($writer){$writer.Dispose()}}
